// Get data from the node before this one
const data = $input.item.json;

// Extract property details from API response
const price = data.price ? `${data.price.toLocaleString()}` : 'N/A';
const address = data.address?.streetAddress || 'Unknown Address';
const city = data.address?.city || '';
const state = data.address?.state || '';
const fullAddress = `${address}, ${city}, ${state}`;
const beds = data.bedrooms ? `${data.bedrooms} bd` : 'N/A';
const baths = data.bathrooms ? `${data.bathrooms} ba` : 'N/A';
const sqft = data.livingArea ? `${data.livingArea.toLocaleString()} sqft` : 'N/A';
const description = data.description || data.resoFacts?.description || '';

// Extract images from API
const allImages = [];
if (data.photos && Array.isArray(data.photos)) {
  data.photos.forEach((photo, i) => {
    if (photo.url || photo.mixedSources?.jpeg) {
      allImages.push({
        url: photo.url || photo.mixedSources.jpeg[photo.mixedSources.jpeg.length - 1]?.url,
        caption: photo.caption || '',
        index: i
      });
    }
  });
}

// Smart selection: prioritize key rooms
const priorityKeywords = ['kitchen', 'living', 'exterior', 'master', 'bedroom', 'front'];
const priorityImages = [];
const regularImages = [];

allImages.forEach(img => {
  const caption = img.caption.toLowerCase();
  if (priorityKeywords.some(keyword => caption.includes(keyword))) {
    priorityImages.push(img);
  } else {
    regularImages.push(img);
  }
});

// Take up to 2 images, prioritizing key rooms
const selectedImages = [
  ...priorityImages.slice(0, 2),
  ...regularImages.slice(0, 2 - priorityImages.length)
].slice(0, 2);

if (selectedImages.length === 0 && allImages.length > 0) {
  // Fallback: just take first 2 images
  selectedImages.push(...allImages.slice(0, 2));
}

return {
  price,
  address: fullAddress,
  beds,
  baths,
  sqft,
  description: description.slice(0, 500), 
  images: selectedImages.map(img => img.url),
  imageCount: selectedImages.length,
  // --- THIS IS THE FIX ---
  // Read name and email from the node's input, not from 'webhookData'
  name: $input.item.json.name,   
  email: $input.item.json.email  
};

